document.addEventListener('DOMContentLoaded',()=>{
  const nav=document.querySelector('.nav');document.querySelector('.hamburger')?.addEventListener('click',()=>nav.classList.toggle('open'));
  document.querySelectorAll('.newsletter form').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();const input=form.querySelector('input[type="email"]');const msg=form.parentElement.querySelector('.form-msg');const ok=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value.trim());msg.className='form-msg '+(ok?'success':'error');msg.textContent=ok?'You’re in. Watch your inbox for RedRoom updates.':'Enter a valid email address to subscribe.';if(ok)form.reset();});});
  document.querySelectorAll('.country-toggle').forEach(btn=>btn.addEventListener('click',()=>btn.closest('.country').classList.toggle('open')));
  const reveals=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target)}}),{threshold:.12});reveals.forEach(el=>io.observe(el));}else reveals.forEach(el=>el.classList.add('in'));
  const track=document.querySelector('.carousel-track');if(track){const slides=[...track.children];const dots=[...document.querySelectorAll('.dot')];let i=0,start=0;const go=n=>{i=(n+slides.length)%slides.length;track.style.transform=`translateX(${-i*100}%)`;dots.forEach((d,x)=>d.classList.toggle('active',x===i));};document.querySelector('[data-next]')?.addEventListener('click',()=>go(i+1));document.querySelector('[data-prev]')?.addEventListener('click',()=>go(i-1));dots.forEach((d,x)=>d.addEventListener('click',()=>go(x)));track.addEventListener('touchstart',e=>start=e.touches[0].clientX,{passive:true});track.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-start;if(Math.abs(dx)>45)go(i+(dx<0?1:-1));});setInterval(()=>go(i+1),6500);}
  const toggles=document.querySelectorAll('[data-workout]');const panel=document.querySelector('.toggle-content');const copy={floor:{title:'Floor',body:'Dumbbells, resistance bands, and bodyweight movements target specific muscle groups each day. Our instructors guide every rep to ensure proper form and maximum results.',meta:'Strength blocks • coached form • daily muscle focus'},tread:{title:'Treadmill',body:'From power walks to all-out sprints, the treadmill portion is designed to torch calories and build cardiovascular endurance. Every speed and incline is coach-led — all levels welcome.',meta:'Intervals • incline pushes • all-out sprints'}};toggles.forEach(btn=>btn.addEventListener('click',()=>{toggles.forEach(b=>b.classList.remove('active'));btn.classList.add('active');const c=copy[btn.dataset.workout];panel.style.opacity=.35;setTimeout(()=>{panel.innerHTML=`<p class="eyebrow">${c.meta}</p><h3>${c.title}</h3><div class="redline"></div><p class="lead">${c.body}</p>`;panel.style.opacity=1;},180);}));
  const filter=document.querySelector('#locationFilter');if(filter){const cards=document.querySelectorAll('.instructor');const count=document.querySelector('#filterCount');const apply=()=>{let shown=0;cards.forEach(card=>{const ok=filter.value==='All Locations'||card.dataset.location===filter.value;card.classList.toggle('hidden',!ok);if(ok)shown++;});count.textContent=`${shown} instructor${shown===1?'':'s'} showing`;};filter.addEventListener('change',apply);apply();}
  document.querySelectorAll('.faq-q').forEach(q=>q.addEventListener('click',()=>{const item=q.closest('.faq-item');document.querySelectorAll('.faq-item').forEach(x=>{if(x!==item)x.classList.remove('open')});item.classList.toggle('open');}));
});
